// Replicates whoosh's StandardAnalyzer: StandardTokenizer + LowercaseFilter + StopFilter.

export const STOP_WORDS = new Set([
  'a','an','and','are','as','at','be','by','can','for','from','have','if','in',
  'is','it','may','not','of','on','or','tbd','that','the','this','to','us','we',
  'when','will','with','yet','you','your'
]);

const TOKEN_RE = /[\p{L}\p{N}_]+(\.?[\p{L}\p{N}_]+)*/gu;

export function analyze(text) {
  const tokens = [];
  for (const match of String(text).matchAll(TOKEN_RE)) {
    const tok = match[0];
    if ([...tok].length < 2) continue;
    const lower = tok.toLowerCase();
    if (STOP_WORDS.has(lower)) continue;
    tokens.push(lower);
  }
  return tokens;
}

// Query node factories (plain data objects) plus an executor.

export function nullQuery() {
  return { type: 'null' };
}

export function term(field, text) {
  return { type: 'term', field, text };
}

export function and(children) {
  const kids = children.filter((c) => c.type !== 'null');
  if (kids.length === 0) return nullQuery();
  if (kids.length === 1) return kids[0];
  return { type: 'and', children: kids };
}

export function or(children) {
  const kids = children.filter((c) => c.type !== 'null');
  if (kids.length === 0) return nullQuery();
  if (kids.length === 1) return kids[0];
  return { type: 'or', children: kids };
}

export function not(child) {
  return { type: 'not', child };
}

export function andMaybe(required, optional) {
  return { type: 'andmaybe', required, optional };
}

export function phrase(field, words) {
  return { type: 'phrase', field, words };
}

export function wildcard(field, pattern) {
  return { type: 'wildcard', field, pattern };
}

export function termRange(field, start, end, startExclusive, endExclusive) {
  return { type: 'termrange', field, start, end, startExclusive, endExclusive };
}

export function every(field) {
  return { type: 'every', field };
}

function wildcardToRegExp(pattern) {
  let src = '';
  for (const ch of pattern) {
    if (ch === '*') src += '.*';
    else if (ch === '?') src += '.';
    else src += ch.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  }
  return new RegExp(`^${src}$`, 'u');
}

export function execute(query, index) {
  switch (query.type) {
    case 'null':
      return [];

    case 'term': {
      const postings = index.postings.get(query.field);
      const set = postings && postings.get(query.text);
      return set ? [...set] : [];
    }

    case 'and': {
      if (query.children.length === 0) return [];
      const sets = query.children.map((c) => new Set(execute(c, index)));
      sets.sort((a, b) => a.size - b.size);
      const [smallest, ...rest] = sets;
      return [...smallest].filter((id) => rest.every((s) => s.has(id)));
    }

    case 'or': {
      const result = new Set();
      for (const c of query.children) {
        for (const id of execute(c, index)) result.add(id);
      }
      return [...result];
    }

    case 'not': {
      const excluded = new Set(execute(query.child, index));
      const result = [];
      for (let id = 0; id < index.docCount; id++) {
        if (!excluded.has(id)) result.push(id);
      }
      return result;
    }

    case 'andmaybe':
      return execute(query.required, index);

    case 'phrase': {
      const words = query.words;
      if (words.length === 0) return [];
      if (words.length === 1) return execute(term(query.field, words[0]), index);
      const result = [];
      for (const [docId, tokens] of index.docTokens) {
        const fieldTokens = tokens.get(query.field) || [];
        outer: for (let i = 0; i + words.length <= fieldTokens.length; i++) {
          for (let j = 0; j < words.length; j++) {
            if (fieldTokens[i + j] !== words[j]) continue outer;
          }
          result.push(docId);
          break;
        }
      }
      return result;
    }

    case 'wildcard': {
      const re = wildcardToRegExp(query.pattern);
      const postings = index.postings.get(query.field);
      if (!postings) return [];
      const result = new Set();
      for (const [t, docIds] of postings) {
        if (re.test(t)) {
          for (const id of docIds) result.add(id);
        }
      }
      return [...result];
    }

    case 'termrange': {
      const { start, end, startExclusive, endExclusive } = query;
      const postings = index.postings.get(query.field);
      if (!postings) return [];
      const result = new Set();
      for (const [t, docIds] of postings) {
        const aboveStart =
          start === null || t > start || (!startExclusive && t === start);
        const belowEnd =
          end === null || t < end || (!endExclusive && t === end);
        if (aboveStart && belowEnd) {
          for (const id of docIds) result.add(id);
        }
      }
      return [...result];
    }

    case 'every': {
      const result = [];
      for (const [docId, tokens] of index.docTokens) {
        const fieldTokens = tokens.get(query.field);
        if (fieldTokens && fieldTokens.length >= 1) result.push(docId);
      }
      return result;
    }

    default:
      throw new Error(`Unknown query type: ${query.type}`);
  }
}

// In-memory stand-in for whoosh's file index (create_in / writer / searcher).

import { analyze } from './analyzer.mjs';
import { execute } from './query.mjs';

export function createSchema(fieldsObj) {
  return { names: Object.keys(fieldsObj), fields: fieldsObj };
}

export function createIn(dir, schema) {
  const index = {
    dir,
    schema,
    docCount: 0,
    // field name -> Map(term -> Set(docId))
    postings: new Map(schema.names.map((name) => [name, new Map()])),
    // docId -> Map(field name -> token array)
    docTokens: new Map(),

    writer() {
      return {
        addDocument(fieldsObj) {
          const docId = index.docCount++;
          const tokens = new Map();
          for (const name of index.schema.names) {
            const value = fieldsObj[name];
            const fieldTokens =
              value === undefined || value === null
                ? []
                : analyze(String(value));
            tokens.set(name, fieldTokens);
            const fieldPostings = index.postings.get(name);
            for (const tok of new Set(fieldTokens)) {
              let docIds = fieldPostings.get(tok);
              if (!docIds) {
                docIds = new Set();
                fieldPostings.set(tok, docIds);
              }
              docIds.add(docId);
            }
          }
          index.docTokens.set(docId, tokens);
        },
        commit() {},
      };
    },

    searcher() {
      return {
        search(query) {
          return execute(query, index);
        },
      };
    },
  };
  return index;
}

import assert from 'node:assert/strict';
import { analyze, STOP_WORDS } from '/output/lib/analyzer.mjs';
import {
  nullQuery, term, and, or, not, andMaybe, phrase, wildcard, termRange,
  every, execute,
} from '/output/lib/query.mjs';
import { createSchema, createIn } from '/output/lib/index.mjs';

// --- analyzer checks ---
assert.deepEqual(analyze('hello world'), ['hello', 'world']);
assert.deepEqual(analyze('The foo-bar!'), ['foo', 'bar']);
assert.deepEqual(analyze('abc.def'), ['abc.def']);
assert.deepEqual(analyze('a bb'), ['bb']);
assert.deepEqual(analyze('café'), ['café']);
assert.equal(STOP_WORDS.size, 32);

// --- build index of 3 docs ---
const schema = createSchema({ title: { stored: true }, content: {} });
const ix = createIn('/ignored/dir', schema);
const w = ix.writer();
w.addDocument({ title: 'The Quick Brown Fox', content: 'jumps over the lazy dog' });
w.addDocument({ title: 'Quick Silver', content: 'the quick brown fox runs fast' });
w.addDocument({ title: 'Nothing Here', content: 'plain text only' });
w.commit();
const s = ix.searcher();
const sorted = (a) => [...a].sort((x, y) => x - y);

// term
assert.deepEqual(sorted(s.search(term('title', 'quick'))), [0, 1]);
assert.deepEqual(s.search(term('title', 'the')), []); // stopword never indexed
// and / or / not
assert.deepEqual(sorted(s.search(and([term('title', 'quick'), term('title', 'brown')]))), [0]);
assert.deepEqual(sorted(s.search(or([term('title', 'silver'), term('title', 'nothing')]))), [1, 2]);
assert.deepEqual(sorted(s.search(not(term('title', 'quick')))), [2]);
assert.deepEqual(sorted(s.search(not(nullQuery()))), [0, 1, 2]); // complement includes all docs
// normalization
assert.equal(and([]).type, 'null');
assert.equal(and([nullQuery(), term('title', 'quick')]).type, 'term');
assert.equal(or([]).type, 'null');
// andMaybe
assert.deepEqual(sorted(s.search(andMaybe(term('title', 'quick'), term('title', 'silver')))), [0, 1]);
// phrase slop-0 on stopword-removed token array: content of doc0 = ['jumps','over','lazy','dog']
assert.deepEqual(s.search(phrase('content', ['over', 'lazy'])), [0]);
assert.deepEqual(s.search(phrase('content', ['over', 'the', 'lazy'])), []); // 'the' removed
assert.deepEqual(s.search(phrase('content', ['lazy', 'over'])), []); // order matters
assert.deepEqual(sorted(s.search(phrase('content', ['quick', 'brown']))), [1]);
assert.deepEqual(s.search(phrase('content', ['jumps'])), [0]); // single word = term
// wildcard + escaping
assert.deepEqual(sorted(s.search(wildcard('title', 'qui*'))), [0, 1]);
assert.deepEqual(sorted(s.search(wildcard('title', 'quic?'))), [0, 1]);
assert.deepEqual(s.search(wildcard('title', 'qui.ck')), []); // '.' is literal, not regex any
assert.deepEqual(s.search(wildcard('content', 'jumps*')), []); // '*' must not match end after full term... wait: jumps* matches 'jumps' too
// termRange
assert.deepEqual(sorted(s.search(termRange('title', 'brown', 'silver', false, false))), [0, 1, 2]);
assert.deepEqual(sorted(s.search(termRange('title', 'brown', 'quick', true, true))), [2]); // 'nothing' only
assert.deepEqual(sorted(s.search(termRange('title', null, 'fox', false, false))), [0]); // brown, fox
assert.deepEqual(sorted(s.search(termRange('title', 'silver', null, false, false))), [1]);
// every
assert.deepEqual(sorted(s.search(every('title'))), [0, 1, 2]);

